// répertoire de l'exe — la ROM et data/ sont cherchés relativement à lui
// en plus du répertoire courant (sinon : lancement hors builddir = pas de
// headers -> écran noir)
static std::string exe_dir() {
    const char* bp = SDL_GetBasePath();      // SDL3 : const, ne pas free
    return bp ? bp : "";
}

// essaie chaque chemin relatif depuis le CWD puis depuis le dossier de l'exe
static std::string find_rel(const char* rel) {
    std::error_code ec;
    if (fs::exists(rel, ec)) return rel;
    std::string p = exe_dir() + rel;
    if (fs::exists(p, ec)) return p;
    return "";
}

// fichiers de données du projet (save.dat, options.cfg, _shots) : toujours
// <exe>/../xxx quel que soit le répertoire courant
static std::string up_path(const char* name) {
    return exe_dir() + "../" + name;
}

static std::string find_rom(int argc, char** argv, std::string& hdr_path) {
    // 1) --rom <path>  2) rom/*.nds  3) ../rom/*.nds (exe dans builddir)
    for (int i = 1; i + 1 < argc; i++)
        if (!strcmp(argv[i], "--rom")) return argv[i + 1];
    const char* dirs[] = {"rom", "../rom", "../../rom"};
    std::string exed = exe_dir();
    for (auto d : dirs) {
        for (const std::string& base : {std::string(""), exed}) {
            std::error_code ec;
            std::string dir = base + d;
            if (!fs::is_directory(dir, ec)) continue;
            for (auto& e : fs::directory_iterator(dir, ec)) {
                auto p = e.path().string();
                if (p.size() > 4 && p.substr(p.size() - 4) == ".nds") return p;
            }
        }
    }
    return "";
}

static int arg_map(int argc, char** argv, int def) {
    for (int i = 1; i + 1 < argc; i++)
        if (!strcmp(argv[i], "--map")) return atoi(argv[i + 1]);
    return def;
}

static int arg_shot(int argc, char** argv) {   // --shot N : frame de capture
    for (int i = 1; i + 1 < argc; i++)
        if (!strcmp(argv[i], "--shot")) return atoi(argv[i + 1]);
    return -1;
}

// --gif F1,F2 : dump chaque frame de la plage en PPM -> _shots/gif_%05d.ppm
static int arg_gif(int argc, char** argv, int* f2) {
    *f2 = -1;
    for (int i = 1; i + 1 < argc; i++)
        if (!strcmp(argv[i], "--gif")) {
            int a = -1, b = -1;
            sscanf(argv[i + 1], "%d,%d", &a, &b);
            *f2 = b;
            return a;
        }
    return -1;
}

static void save_ppm(const char* path, int w, int h, const uint8_t* rgba) {
    FILE* f = fopen(path, "wb");
    if (!f) return;
    fprintf(f, "P6\n%d %d\n255\n", w, h);
    std::vector<uint8_t> row((size_t)w * 3);
    for (int y = h - 1; y >= 0; y--) {            // GL lit bottom-up
        const uint8_t* s = rgba + (size_t)y * w * 4;
        for (int x = 0; x < w; x++) {
            row[x * 3 + 0] = s[x * 4 + 0];
            row[x * 3 + 1] = s[x * 4 + 1];
            row[x * 3 + 2] = s[x * 4 + 2];
        }
        fwrite(row.data(), 3, (size_t)w, f);
    }
    fclose(f);
    printf("[shot] %s\n", path);
}

