static void neo_gfill(ImDrawList* dl, ImVec2 p0, ImVec2 p1, float rad,
                      ImU32 ct, ImU32 cb);      // défini plus bas (kit Néo)
// panneau « verre » : ombre portée + fond translucide + liseré (maquette)
static void ui_panel_th(ImDrawList* dl, ImVec2 p0, ImVec2 p1, float rad) {
    const UiTh* T = ui_theme();
    if (g_theme_eff) {                        // box-shadow 0 14px 40px .45
        dl->AddRectFilled({p0.x + 3, p0.y + 8}, {p1.x + 3, p1.y + 8},
            IM_COL32(0, 0, 0, 60), rad + 3.f);
        dl->AddRectFilled({p0.x + 1, p0.y + 4}, {p1.x + 1, p1.y + 4},
            IM_COL32(0, 0, 0, 45), rad + 2.f);
    }
    if (th_pop()) {                   // POP : sticker papier (avant th_neo
        pop_stk(dl, p0, p1, POP_PAP, rad,          // car th_neo inclut 4)
            fmaxf(3.f, rad * 0.3f), 4.f);
        return;
    }
    if (th_neo())                     // Néo : dégradé vertical maquette
        neo_gfill(dl, p0, p1, rad,
            IM_COL32(24, 32, 56, 240), IM_COL32(14, 19, 34, 244));
    else
        dl->AddRectFilled(p0, p1, T->fill, rad);
    dl->AddRect(p0, p1, T->edge, rad, 0, 1.5f);
}
// fenêtre PokeMMO : ombre + anthracite #2e3439 + bandeau titre acier #b6c4cb
static void ui_window_th(ImDrawList* dl, ImVec2 p0, ImVec2 p1,
                         const char* title, ImFont* f, float u) {
    dl->AddRectFilled({p0.x + 3, p0.y + 5}, {p1.x + 3, p1.y + 5},
        IM_COL32(0, 0, 0, 90), 10.f * u);
    if (th_pop()) {
        pop_stk(dl, p0, p1, POP_PAP, 10.f * u, 4.f * u, 4.f * u);
        if (title)
            dl->AddText(f, 13.f * u, {p0.x + 14.f * u, p0.y + 11.f * u},
                POP_INK, title);
        return;
    }
    if (th_neo()) {
        // Néo : fenêtre glass navy + titre maquette (puce rouge + label discret)
        neo_gfill(dl, p0, p1, 10.f * u,
            IM_COL32(24, 32, 56, 242), IM_COL32(13, 18, 32, 246));
        dl->AddRect(p0, p1, IM_COL32(42, 54, 84, 255), 10.f * u, 0, 1.4f * u);
        if (title) {
            dl->AddRectFilled({p0.x + 12.f * u, p0.y + 13.f * u},
                {p0.x + 20.f * u, p0.y + 21.f * u},
                IM_COL32(232, 69, 90, 255), 2.5f * u);
            dl->AddText(f, 11.f * u, {p0.x + 28.f * u, p0.y + 11.f * u},
                IM_COL32(142, 161, 194, 255), title);
            dl->AddLine({p0.x + 12.f * u, p0.y + 32.f * u},
                {p1.x - 12.f * u, p0.y + 32.f * u},
                IM_COL32(42, 54, 84, 255), 1.f);
        }
        return;
    }
    dl->AddRectFilled(p0, p1, IM_COL32(46, 52, 57, 235), 10.f * u);
    dl->AddRect(p0, p1, IM_COL32(182, 196, 203, 70), 10.f * u, 0, 1.4f * u);
    ImVec2 h0{p0.x + 2.f * u, p0.y + 2.f * u},
           h1{p1.x - 2.f * u, p0.y + 30.f * u};
    dl->AddRectFilled(h0, h1, IM_COL32(182, 196, 203, 255), 8.f * u);
    if (title)
        dl->AddText(f, 12.f * u, {h0.x + 12.f * u, h0.y + 7.f * u},
            IM_COL32(46, 52, 57, 255), title);
}
// fond plein écran : ciel dégradé + stries + bandeau violet bas
static void sb_bg(ImDrawList* dl, float w, float h, bool strip = true) {
    if (th_pop()) {               // POP : papier crème uni
        dl->AddRectFilled({0, 0}, {w, h}, POP_PAP);
        (void)strip;
        return;
    }
    if (th_neo()) {
        // Néo : nuit navy maquette + stries fines (pas de bandeau bas)
        dl->AddRectFilledMultiColor({0, 0}, {w, h},
            IM_COL32(13, 18, 32, 255), IM_COL32(13, 18, 32, 255),
            IM_COL32(6, 9, 17, 255), IM_COL32(6, 9, 17, 255));
        for (float yy = 0; yy < h; yy += 6.f)
            dl->AddLine({0, yy}, {w, yy}, IM_COL32(30, 40, 62, 70));
        (void)strip;
        return;
    }
    if (g_theme_eff == 1) {
        dl->AddRectFilledMultiColor({0, 0}, {w, h},
            IM_COL32(18, 26, 42, 255), IM_COL32(18, 26, 42, 255),
            IM_COL32(8, 12, 22, 255), IM_COL32(8, 12, 22, 255));
        for (float yy = 0; yy < h; yy += 6.f)
            dl->AddLine({0, yy}, {w, yy}, IM_COL32(32, 44, 66, 90));
        if (strip) {
            dl->AddRectFilled({0, h - 70}, {w, h}, IM_COL32(122, 32, 44, 255));
            dl->AddRectFilled({0, h - 70}, {w, h - 64}, IM_COL32(232, 69, 90, 255));
        }
        return;
    }
    if (g_theme_eff == 2) {
        dl->AddRectFilledMultiColor({0, 0}, {w, h},
            IM_COL32(240, 246, 252, 255), IM_COL32(240, 246, 252, 255),
            IM_COL32(214, 226, 242, 255), IM_COL32(214, 226, 242, 255));
        for (float yy = 0; yy < h; yy += 6.f)
            dl->AddLine({0, yy}, {w, yy}, IM_COL32(255, 255, 255, 130));
        if (strip) {
            dl->AddRectFilled({0, h - 70}, {w, h}, IM_COL32(52, 110, 225, 255));
            dl->AddRectFilled({0, h - 70}, {w, h - 64}, IM_COL32(120, 168, 240, 255));
        }
        return;
    }
    dl->AddRectFilledMultiColor({0, 0}, {w, h},
        IM_COL32(150, 195, 235, 255), IM_COL32(150, 195, 235, 255),
        IM_COL32(240, 245, 250, 255), IM_COL32(240, 245, 250, 255));
    for (float yy = 0; yy < h; yy += 6.f)
        dl->AddLine({0, yy}, {w, yy}, IM_COL32(160, 205, 240, 110));
    if (strip) {
        dl->AddRectFilled({0, h - 70}, {w, h}, B_PURP);
        dl->AddRectFilled({0, h - 70}, {w, h - 64}, B_PURP2);
    }
}
