// tokens maquette : panel #182038->#0e1322 / bord #2a3654 / accent #e8455a
static ImFont* neo_font() {
    auto& fl = *ImGui::GetIO().Fonts;
    return fl.Fonts.Size > 1 ? fl.Fonts[1] : fl.Fonts[0];
}
// texture plein cadre du titre POP (pop_title.jpg, fallback uni)
static GLuint ui_upload(const Image& im, bool linear);
static GLuint pop_title_tex() {
    static GLuint t = 0; static bool done = false;
    if (done) return t; done = true;
    int w, h, n;
    if (unsigned char* d = stbi_load(up_path("ui/pop_title.jpg").c_str(),
                                     &w, &h, &n, 4)) {
        Image im; im.create(w, h); memcpy(im.px.data(), d, (size_t)w*h*4);
        stbi_image_free(d);
        t = ui_upload(im, true);
    }
    return t;
}
static float neo_txt(ImDrawList* dl, const std::string& s, float x, float y,
                     ImU32 c, float px) {
    dl->AddText(neo_font(), px, {x, y}, c, s.c_str());
    return neo_font()->CalcTextSizeA(px, 1e30f, 0, s.c_str()).x;
}
static float neo_tw(const std::string& s, float px) {
    return neo_font()->CalcTextSizeA(px, 1e30f, 0, s.c_str()).x;
}
// filtre les glyphes absents de la fonte (sinon ImGui affiche « ? »)
static std::string neo_clean(const char* s) {
    ImFont* f = neo_font();
    std::string o, in = s;
    for (size_t i = 0, n = in.size(); i < n;) {
        size_t at = i;
        int cp = msg_next_utf8(in, i);
        if (i <= at) { i = at + 1; continue; }
        if (f->FindGlyphNoFallback((ImWchar)cp))
            o.append(in, at, i - at);
    }
    return o;
}
// remplissage dégradé VERTICAL dans un rectangle ARRONDI : chemin convexes
// triangulé en éventail + couleur interpolée par vertex (le
// AddRectFilledMultiColor d'ImGui est toujours carré -> coins carrés visibles)
static ImU32 neo_lerp(ImU32 a, ImU32 b, float t) {
    auto ch = [a, b, t](int s) {
        int va = (int)((a >> s) & 255), vb = (int)((b >> s) & 255);
        return va + (int)((vb - va) * t + .5f);
    };
    return IM_COL32(ch(0), ch(8), ch(16), ch(24));
}
static void neo_gfill(ImDrawList* dl, ImVec2 p0, ImVec2 p1, float rad,
                      ImU32 ct, ImU32 cb) {
    dl->PathRect(p0, p1, rad);
    int n = dl->_Path.Size;
    if (n < 3) { dl->_Path.Size = 0; return; }
    const ImVec2* vtx = dl->_Path.Data;
    float h = p1.y - p0.y;
    ImVec2 wuv = ImGui::GetIO().Fonts->TexUvWhitePixel;
    unsigned base = dl->_VtxCurrentIdx;
    dl->PrimReserve((n - 2) * 3, n);
    for (int i = 0; i < n; i++) {
        float t = h > 0.f ? (vtx[i].y - p0.y) / h : 0.f;
        if (t < 0.f) t = 0.f; if (t > 1.f) t = 1.f;
        dl->PrimWriteVtx(vtx[i], wuv, neo_lerp(ct, cb, t));
    }
    for (int i = 2; i < n; i++) {
        dl->PrimWriteIdx((ImDrawIdx)base);
        dl->PrimWriteIdx((ImDrawIdx)(base + i - 1));
        dl->PrimWriteIdx((ImDrawIdx)(base + i));
    }
    dl->_Path.Size = 0;
}
// dégradé HORIZONTAL dans un rect arrondi (cartes teintées par type)
static void neo_hfill(ImDrawList* dl, ImVec2 p0, ImVec2 p1, float rad,
                      ImU32 cl, ImU32 cr) {
    dl->PathRect(p0, p1, rad);
    int n = dl->_Path.Size;
    if (n < 3) { dl->_Path.Size = 0; return; }
    const ImVec2* vtx = dl->_Path.Data;
    float w = p1.x - p0.x;
    ImVec2 wuv = ImGui::GetIO().Fonts->TexUvWhitePixel;
    unsigned base = dl->_VtxCurrentIdx;
    dl->PrimReserve((n - 2) * 3, n);
    for (int i = 0; i < n; i++) {
        float t = w > 0.f ? (vtx[i].x - p0.x) / w : 0.f;
        if (t < 0.f) t = 0.f; if (t > 1.f) t = 1.f;
        dl->PrimWriteVtx(vtx[i], wuv, neo_lerp(cl, cr, t));
    }
    for (int i = 2; i < n; i++) {
        dl->PrimWriteIdx((ImDrawIdx)base);
        dl->PrimWriteIdx((ImDrawIdx)(base + i - 1));
        dl->PrimWriteIdx((ImDrawIdx)(base + i));
    }
    dl->_Path.Size = 0;
}
// .panel : dégradé navy + bord #2a3654 + ombre douce
static void neo_panel(ImDrawList* dl, ImVec2 p0, ImVec2 p1, float rad) {
    dl->AddRectFilled({p0.x + 2, p0.y + 8}, {p1.x + 2, p1.y + 8},
        IM_COL32(0, 0, 0, 60), rad);
    neo_gfill(dl, p0, p1, rad,
        IM_COL32(24, 32, 56, 235), IM_COL32(14, 19, 34, 240));
    dl->AddRect(p0, p1, IM_COL32(42, 54, 84, 255), rad, 0, 1.5f);
}
// mini Pokéball : moitié rouge + moitié blanc + bande + bouton (pin bordure)
static void neo_pokeball(ImDrawList* dl, ImVec2 c, float r,
                         bool gloss = true) {
    const float PI = 3.14159265f;
    dl->PathArcTo(c, r, PI, 2.f * PI);              // haut = rouge
    dl->PathFillConvex(IM_COL32(232, 69, 90, 255));
    dl->PathArcTo(c, r, 0.f, PI);                   // bas = blanc cassé
    dl->PathFillConvex(IM_COL32(238, 241, 247, 255));
    dl->AddRectFilled({c.x - r, c.y - r * 0.16f}, {c.x + r, c.y + r * 0.16f},
        IM_COL32(14, 19, 34, 255));                 // bande sombre
    dl->AddCircleFilled(c, r * 0.32f, IM_COL32(238, 241, 247, 255));
    dl->AddCircle(c, r * 0.32f, IM_COL32(14, 19, 34, 255), 0, 1.f);
    if (gloss)   // reflet haut-gauche sur la moitié rouge
        dl->AddCircleFilled({c.x - r * 0.38f, c.y - r * 0.52f}, r * 0.16f,
            IM_COL32(255, 235, 235, 200));
    dl->AddCircle(c, r, IM_COL32(10, 14, 26, 255), 0, 1.5f);
}
// glyphe plat monochrome pour une entrée du menu X (c = centre du slot)
static void neo_icon(ImDrawList* dl, ImVec2 c, int opt, float u, ImU32 col) {
    const float PI = 3.14159265f;
    float s = 5.5f * u;                    // demi-taille du glyphe
    switch (opt) {
        case 0: {                          // Pokédex : écran + charnière
            dl->AddRectFilled({c.x - s * 0.8f, c.y - s},
                {c.x + s * 0.8f, c.y + s}, col, 1.5f * u);
            dl->AddRectFilled({c.x - s * 0.45f, c.y - s * 0.55f},
                {c.x + s * 0.45f, c.y + s * 0.1f},
                IM_COL32(14, 19, 34, 255), 1.f * u);
            break;
        }
        case 1:                            // Pokémon : mini ball
            neo_pokeball(dl, c, s * 0.9f, false);
            break;
        case 2: {                          // Sac : corps + anse
            dl->PathArcTo({c.x, c.y - s * 0.35f}, s * 0.62f, PI, 2.f * PI);
            dl->PathStroke(col, 0, 1.6f * u);
            dl->AddRectFilled({c.x - s * 0.75f, c.y - s * 0.35f},
                {c.x + s * 0.75f, c.y + s * 0.8f}, col, 2.5f * u);
            break;
        }
        case 3: {                          // Carte : cadre + puce + ligne
            dl->AddRect({c.x - s, c.y - s * 0.7f}, {c.x + s, c.y + s * 0.7f},
                col, 1.5f * u, 0, 1.6f * u);
            dl->AddCircleFilled({c.x - s * 0.5f, c.y - s * 0.15f},
                s * 0.22f, col);
            dl->AddLine({c.x - s * 0.5f, c.y + s * 0.35f},
                {c.x + s * 0.5f, c.y + s * 0.35f}, col, 1.4f * u);
            break;
        }
        case 4: {                          // Sauver : disquette
            dl->AddRect({c.x - s * 0.85f, c.y - s * 0.85f},
                {c.x + s * 0.85f, c.y + s * 0.85f}, col, 1.2f * u, 0,
                1.6f * u);
            dl->AddRectFilled({c.x - s * 0.3f, c.y - s * 0.85f},
                {c.x + s * 0.45f, c.y - s * 0.25f}, col);
            dl->AddRectFilled({c.x - s * 0.45f, c.y + s * 0.1f},
                {c.x + s * 0.45f, c.y + s * 0.85f}, col, 0.8f * u);
            break;
        }
        case 5: {                          // Options : engrenage
            dl->AddCircle(c, s * 0.55f, col, 0, 2.f * u);
            for (int k = 0; k < 4; k++) {
                float a = k * 0.7854f;
                dl->AddLine({c.x + cosf(a) * s * 0.5f,
                    c.y + sinf(a) * s * 0.5f},
                    {c.x + cosf(a) * s * 0.95f,
                     c.y + sinf(a) * s * 0.95f}, col, 1.6f * u);
            }
            break;
        }
        case 6: {                          // Quitter : porte + flèche
            dl->AddRect({c.x - s * 0.9f, c.y - s * 0.8f},
                {c.x + s * 0.2f, c.y + s * 0.8f}, col, 1.2f * u, 0,
                1.6f * u);
            dl->AddLine({c.x - s * 0.1f, c.y}, {c.x + s * 0.9f, c.y},
                col, 1.8f * u);
            dl->AddLine({c.x + s * 0.45f, c.y - s * 0.4f},
                {c.x + s * 0.9f, c.y}, col, 1.8f * u);
            dl->AddLine({c.x + s * 0.45f, c.y + s * 0.4f},
                {c.x + s * 0.9f, c.y}, col, 1.8f * u);
            break;
        }
        case 7: {                          // Zone : épingle carte
            dl->AddCircleFilled({c.x, c.y - s * 0.25f}, s * 0.6f, col);
            dl->AddCircleFilled({c.x, c.y - s * 0.25f}, s * 0.25f,
                IM_COL32(14, 19, 34, 255));
            dl->AddLine({c.x, c.y + s * 0.3f}, {c.x, c.y + s * 0.9f},
                col, 1.8f * u);
            break;
        }
    }
}
// textbox Néo enrichie (réf fal) : rim + shelf glass + onglet corail + inset
static void neo_msgbox(ImDrawList* dl, ImVec2 p0, ImVec2 p1, float u,
                       bool tab = true) {
    float rad = 6.f * u;
    // ombre portée + rim extérieur sombre
    dl->AddRectFilled({p0.x + 2, p0.y + 8}, {p1.x + 2, p1.y + 8},
        IM_COL32(0, 0, 0, 70), rad + 2.f);
    dl->AddRect({p0.x - 1.5f, p0.y - 1.5f}, {p1.x + 1.5f, p1.y + 1.5f},
        IM_COL32(8, 11, 20, 220), rad + 2.f, 0, 2.f);
    // corps : dégradé navy (haut plus lumineux que le panel standard)
    neo_gfill(dl, p0, p1, rad,
        IM_COL32(30, 40, 70, 242), IM_COL32(13, 18, 32, 246));
    // shelf glass : bandeau clair arrondi en haut qui s'estompe
    dl->AddRectFilledMultiColor({p0.x + 2.f * u, p0.y + 2.f * u},
        {p1.x - 2.f * u, p0.y + 12.f * u},
        IM_COL32(88, 110, 165, 95), IM_COL32(88, 110, 165, 95),
        IM_COL32(88, 110, 165, 8), IM_COL32(88, 110, 165, 8));
    // liseré brillant juste sous le bord supérieur
    dl->AddRect({p0.x + 1.5f, p0.y + 1.5f}, {p1.x - 1.5f, p1.y - 1.5f},
        IM_COL32(86, 104, 158, 175), rad - 1.5f, 0, 1.f);
    // inset : puits à texte légèrement plus sombre
    ImVec2 i0{p0.x + 5.f * u, p0.y + 5.5f * u},
           i1{p1.x - 5.f * u, p1.y - 4.5f * u};
    dl->AddRectFilled(i0, i1, IM_COL32(9, 13, 24, 110), 4.f * u);
    dl->AddRect(i0, i1, IM_COL32(42, 54, 84, 150), 4.f * u, 0, 1.f);
    // pin Pokéball à cheval sur le bord haut-gauche
    if (tab) {
        ImVec2 c{p0.x + 15.f * u, p0.y};
        dl->AddCircleFilled({c.x + 1.5f, c.y + 2.5f}, 7.f * u,
            IM_COL32(0, 0, 0, 80));
        neo_pokeball(dl, c, 6.5f * u);
    }
    // bord principal par-dessus tout
    dl->AddRect(p0, p1, IM_COL32(46, 60, 94, 255), rad, 0, 1.5f);
}
// .hd : libellé mono espacé + filet dégradé (« LABEL <em> ————— »)
static void neo_hd(ImDrawList* dl, const std::string& lab, const char* em,
                   float x, float y, float xr, float u) {
    float xx = neo_txt(dl, lab, x, y, IM_COL32(95, 114, 150, 255), 10.5f * u);
    if (em)
        xx += neo_txt(dl, em, x + xx + 4.f * u, y,
            IM_COL32(232, 69, 90, 255), 10.5f * u) + 4.f * u;
    dl->AddRectFilledMultiColor({x + xx + 10.f * u, y + 6.f * u},
        {xr, y + 7.f * u},
        IM_COL32(42, 54, 84, 255), IM_COL32(42, 54, 84, 0),
        IM_COL32(42, 54, 84, 0), IM_COL32(42, 54, 84, 255));
}
// .lic : ligne liste — sel = voile rouge + liseré (pas de rail latéral)
static void neo_lic(ImDrawList* dl, ImVec2 p0, ImVec2 p1, bool sel,
                    float rad) {
    if (!sel) return;
    dl->AddRectFilled(p0, p1, IM_COL32(232, 69, 90, 41), rad);
    dl->AddRect(p0, p1, IM_COL32(232, 69, 90, 140), rad, 0, 1.5f);
}
// .btn : bouton ghost — sel = plein rouge
static void neo_btn(ImDrawList* dl, ImVec2 p0, ImVec2 p1, bool sel,
                    float rad) {
    if (sel) {
        dl->AddRectFilled(p0, p1, IM_COL32(232, 69, 90, 255), rad);
        dl->AddRect(p0, p1, IM_COL32(240, 122, 138, 255), rad, 0, 1.5f);
    } else {
        dl->AddRectFilled(p0, p1, IM_COL32(22, 29, 46, 235), rad);
        dl->AddRect(p0, p1, IM_COL32(42, 54, 84, 255), rad, 0, 1.5f);
    }
}
// .gauge : piste #1a2438 rond, fill dégradé (vert/ambre/rouge selon frac)
static void neo_gauge(ImDrawList* dl, ImVec2 p0, float w, float frac,
                      float h) {
    frac = frac < 0 ? 0 : frac > 1 ? 1 : frac;
    dl->AddRectFilled(p0, {p0.x + w, p0.y + h}, IM_COL32(26, 36, 56, 255),
        h * 0.5f);
    if (frac <= 0.f) return;
    ImU32 c0, c1;
    if (frac > 0.5f)       { c0 = IM_COL32(74, 200, 138, 255);
                             c1 = IM_COL32(126, 224, 174, 255); }
    else if (frac > 0.25f) { c0 = IM_COL32(232, 176, 69, 255);
                             c1 = IM_COL32(240, 207, 122, 255); }
    else                   { c0 = IM_COL32(232, 69, 90, 255);
                             c1 = IM_COL32(240, 122, 138, 255); }
    dl->AddRectFilledMultiColor(p0, {p0.x + w * frac, p0.y + h},
        c0, c1, c1, c0);
}
// .xp : barre XP bleue fine
static void neo_xp(ImDrawList* dl, ImVec2 p0, float w, float frac, float h) {
    frac = frac < 0 ? 0 : frac > 1 ? 1 : frac;
    dl->AddRectFilled(p0, {p0.x + w, p0.y + h}, IM_COL32(26, 36, 56, 255),
        h * 0.5f);
    if (frac > 0.f)
        dl->AddRectFilled(p0, {p0.x + w * frac, p0.y + h},
            IM_COL32(90, 138, 240, 255), h * 0.5f);
}
// .chip : étiquette mono bordée (objet, filtre…)
[[maybe_unused]] static float neo_chip(ImDrawList* dl,
    const std::string& s, float x, float y,
                      ImU32 c, ImU32 edge, float u) {
    float tw = neo_tw(s, 9.f * u);
    ImVec2 t0{x, y}, t1{x + tw + 16.f * u, y + 17.f * u};
    dl->AddRectFilled(t0, t1, IM_COL32(28, 36, 56, 255), 5.f * u);
    dl->AddRect(t0, t1, edge, 5.f * u, 0, 1.f);
    neo_txt(dl, s, x + 8.f * u, y + 4.5f * u, c, 9.f * u);
    return t1.x - t0.x;
}
// .tag : pastille type/statut — fond et bord teintés à ~13 %/40 %
static float neo_tag(ImDrawList* dl, const std::string& s, float x, float y,
                     ImU32 c, float u) {
    float tw = neo_tw(s, 9.f * u);
    ImVec2 t0{x, y}, t1{x + tw + 18.f * u, y + 16.f * u};
    dl->AddRectFilled(t0, t1, (c & 0x00FFFFFF) | 0x22000000, 5.f * u);
    dl->AddRect(t0, t1, (c & 0x00FFFFFF) | 0x66000000, 5.f * u, 0, 1.f);
    neo_txt(dl, s, x + 9.f * u, y + 3.5f * u, c, 9.f * u);
    return t1.x - t0.x;
}
// ♂ / ♀ dessinés en vectoriel (les glyphes manquent à la fonte)
static void neo_gender(ImDrawList* dl, ImVec2 p, bool female, float r) {
    ImU32 c = female ? IM_COL32(240, 120, 168, 255)
                     : IM_COL32(106, 176, 240, 255);
    float t = r * 0.28f;
    if (female) {                       // ♀ : cercle + croix dessous
        dl->AddCircle({p.x, p.y - r * 0.35f}, r * 0.62f, c, 0, t);
        dl->AddLine({p.x, p.y + r * 0.3f}, {p.x, p.y + r * 1.15f}, c, t);
        dl->AddLine({p.x - r * 0.42f, p.y + r * 0.75f},
                    {p.x + r * 0.42f, p.y + r * 0.75f}, c, t);
    } else {                            // ♂ : cercle + flèche NE
        dl->AddCircle({p.x - r * 0.28f, p.y + r * 0.28f}, r * 0.62f, c,
            0, t);
        dl->AddLine({p.x + r * 0.15f, p.y - r * 0.15f},
                    {p.x + r * 0.85f, p.y - r * 0.85f}, c, t);
        dl->AddLine({p.x + r * 0.32f, p.y - r * 0.85f},
                    {p.x + r * 0.85f, p.y - r * 0.85f}, c, t);
        dl->AddLine({p.x + r * 0.85f, p.y - r * 0.85f},
                    {p.x + r * 0.85f, p.y - r * 0.32f}, c, t);
    }
}
// losange ◈ dessiné (marqueur objet tenu)
static void neo_diamond(ImDrawList* dl, ImVec2 c, float r, ImU32 col) {
    ImVec2 v[4] = {{c.x, c.y - r}, {c.x + r * 0.7f, c.y},
                   {c.x, c.y + r}, {c.x - r * 0.7f, c.y}};
    dl->AddConvexPolyFilled(v, 4, col);
}
// flèche dessinée (la fonte n'a pas ◂▸↑↓) : dir 0=◂ 1=▸ 2=▲ 3=▼
static void neo_arr(ImDrawList* dl, ImVec2 c, int dir, float r, ImU32 col) {
    ImVec2 v[3];
    switch (dir & 3) {
    case 0: v[0] = {c.x - r, c.y}; v[1] = {c.x + r * 0.6f, c.y - r};
            v[2] = {c.x + r * 0.6f, c.y + r}; break;
    case 1: v[0] = {c.x + r, c.y}; v[1] = {c.x - r * 0.6f, c.y - r};
            v[2] = {c.x - r * 0.6f, c.y + r}; break;
    case 2: v[0] = {c.x, c.y - r}; v[1] = {c.x - r, c.y + r * 0.6f};
            v[2] = {c.x + r, c.y + r * 0.6f}; break;
    default:v[0] = {c.x, c.y + r}; v[1] = {c.x - r, c.y - r * 0.6f};
            v[2] = {c.x + r, c.y - r * 0.6f}; break;
    }
    dl->AddTriangleFilled(v[0], v[1], v[2], col);
}
// halo radial doux : ellipses concentriques à alpha croissant
// (AddEllipseFilled plat = bords durs, moche)
static void neo_halo(ImDrawList* dl, ImVec2 c, float rx, float ry,
                     int r, int g, int b, int amax, int steps = 24) {
    for (int k = steps; k >= 1; k--) {
        float rf = (float)k / steps;
        int a = amax * (steps - k) / steps;
        dl->AddEllipseFilled(c, {rx * rf + 1.f, ry * rf + 1.f},
            IM_COL32(r, g, b, a), 0.f, 48);
    }
}
// étiquette de locuteur pour la pastille du dialogue : le nom du gfx
// overworld (classe dresseur / PNJ) passé au français pour les cas usuels,
// sinon joli libellé (« OLD_MAN » -> « Old Man ») ; "" = pas de pastille
static std::string neo_npc_label(const char* n) {
    if (!n || !*n) return {};
    static const char* SKIP[] = {   // objets/variantes sans identité
        "DUMMY", "UNUSED", "VAR_", "UNK_", "PLAYER_", "MAP_", "MAILBOX",
        "SIGNBOARD", "ARROW_", "GYM_SIGNPOST", "TRAINER_TIPS", "BERRY_",
        "SNOWBALL", "STRENGTH_", "ROCK_SMASH", "CUT_TREE", "POKEBALL",
        "VENT", "BOOK", "BRIEFCASE", "BOLLARD", "MOSS_ROCK", "ICE_ROCK",
        "DIST_WORLD",
    };
    for (auto s : SKIP) if (!strncmp(n, s, strlen(s))) return {};
    static const std::pair<const char*, const char*> T[] = {
        {"PROF_ROWAN", "PROF. SORBIER"}, {"PROF_OAK", "PROF. CHEN"},
        {"MOM", "MAMAN"}, {"POKECENTER_NURSE", "INFIRMIÈRE"},
        {"RECEPTIONIST", "HÔTESSE"}, {"GYM_GUIDE", "CONSEILLER"},
        {"CASHIER_M", "CAISSIER"}, {"CASHIER_F", "CAISSIÈRE"},
        {"MYSTERY_GIFT_DELIVERYMAN", "LIVREUR"},
        {"YOUNGSTER", "GAMIN"}, {"LASS", "FILLETTE"},
        {"SCHOOL_KID_M", "ÉCOLIER"}, {"SCHOOL_KID_F", "ÉCOLIÈRE"},
        {"BUG_CATCHER", "SCOUT"}, {"NINJA_BOY", "NINJA"},
        {"TWINS", "JUMELLES"}, {"TWIN", "JUMELLE"},
        {"BATTLE_GIRL", "COMBATTANTE"}, {"BLACK_BELT", "KARATÉKA"},
        {"POKEMON_BREEDER_M", "ÉLEVEUR"}, {"POKEMON_BREEDER_F", "ÉLEVEUSE"},
        {"GUITARIST", "GUITARISTE"}, {"IDOL", "STAR"},
        {"ACE_TRAINER_M", "TOPDRESSEUR"}, {"ACE_TRAINER_F", "TOPDRESSEUSE"},
        {"ACE_TRAINER_SNOW_M", "TOPDRESSEUR"},
        {"ACE_TRAINER_SNOW_F", "TOPDRESSEUSE"},
        {"POKEFAN_M", "POKÉFAN"}, {"POKEFAN_F", "POKÉFAN"},
        {"EXPERT_M", "EXPERT"}, {"EXPERT_F", "EXPERTE"},
        {"COLLECTOR", "COLLECTIONNEUR"}, {"HIKER", "MONTAGNARD"},
        {"REPORTER", "JOURNALISTE"}, {"CAMERAMAN", "CAMÉRAMAN"},
        {"SCIENTIST_M", "SCIENTIFIQUE"}, {"SCIENTIST_F", "SCIENTIFIQUE"},
        {"ROUGHNECK", "LOUBARD"}, {"POLICEMAN", "AGENT"},
        {"GENTLEMAN", "GENTLEMAN"}, {"SOCIALITE", "MONDAINE"},
        {"CYCLIST_M", "CYCLISTE"}, {"CYCLIST_F", "CYCLISTE"},
        {"WORKER", "OUVRIER"}, {"RANCHER", "RANCHER"},
        {"COWGIRL", "COWGIRL"}, {"CLOWN", "CLOWN"},
        {"ARTIST", "ARTISTE"}, {"JOGGER", "JOGGEUR"},
        {"SWIMMER_M", "NAGEUR"}, {"SWIMMER_F", "NAGEUSE"},
        {"TUBER_M", "GAMIN"}, {"TUBER_F", "GAMINE"},
        {"RUIN_MANIAC", "RUINOPHILE"}, {"CAMPER", "CAMPEUR"},
        {"PICNICKER", "FAN DE PIQUE-NIQUE"}, {"FISHERMAN", "PÊCHEUR"},
        {"PARASOL_LADY", "DAME PARASOL"}, {"SAILOR", "MARIN"},
        {"WAITER", "SERVEUR"}, {"WAITRESS", "SERVEUSE"},
        {"RICH_BOY", "RICHARD"}, {"LADY", "MONDAINE"},
        {"SNOWPOINT_NPC_M", "HABITANT"}, {"SNOWPOINT_NPC_F", "HABITANTE"},
        {"PSYCHIC", "PSY"}, {"OLD_MAN", "VIEIL HOMME"},
        {"OLD_WOMAN", "VIEILLE DAME"}, {"MIDDLE_AGED_MAN", "MONSIEUR"},
        {"MIDDLE_AGED_WOMAN", "MADAME"}, {"MAID", "DOMESTIQUE"},
        {"UNUSED_MAN", "MONSIEUR"}, {"GRUNT_M", "SBIRE GALAXIE"},
        {"GRUNT_F", "SBIRE GALAXIE"}, {"CYRUS", "HÉLIO"},
        {"MARS", "MARS"}, {"SATURN", "SATURNE"}, {"JUPITER", "JUPITER"},
        {"ROARK", "PIERRICK"}, {"GARDENIA", "FLO"},
        {"CRASHER_WAKE", "LOVITE"}, {"MAYLENE", "MÉLINA"},
        {"FANTINA", "KIMERA"}, {"CANDICE", "GLADYS"},
        {"BYRON", "CHARLES"}, {"VOLKNER", "TANGUY"},
        {"AARON", "AARON"}, {"BERTHA", "TERRY"}, {"FLINT", "ADRIEN"},
        {"LUCIAN", "LUCIANO"}, {"CYNTHIA", "CYNTHIA"},
        {"PALMER", "KONRAD"}, {"CHERYL", "SARA"}, {"RILEY", "RILEY"},
        {"MARLEY", "REBECCA"}, {"BUCK", "CORNELIUS"}, {"MIRA", "MAÉVA"},
        {"BARRY", "BARRY"}, {"JASMINE", "JASMINE"},
        {"KID_WITH_NDS", "GAMIN"}, {"BABY_IN_PRAM", "BÉBÉ"},
        {"TEALA", "TEALA"},
    };
    for (auto& kv : T) if (!strcmp(n, kv.first)) return kv.second;
    // repli : « ACE_TRAINER_M » -> « Ace Trainer M »
    std::string s;
    bool cap = true;
    for (const char* p = n; *p; p++) {
        if (*p == '_') { s += ' '; cap = true; continue; }
        s += cap ? *p : (char)tolower((unsigned char)*p);
        cap = false;
    }
    return s;
}
// casse UTF-8 (latin-1 accentué) pour pastilles/comparaisons de noms
static std::string neo_upper(const std::string& s) {
    std::string o = s;
    for (size_t i = 0; i < o.size(); i++) {
        unsigned char c = (unsigned char)o[i];
        if (c >= 'a' && c <= 'z') o[i] = (char)(c - 32);
        else if (c == 0xC3 && i + 1 < o.size()) {
            unsigned char d = (unsigned char)o[i + 1];
            if (d >= 0xA0 && d <= 0xBE && d != 0xB7) o[i + 1] = (char)(d - 0x20);
        }
    }
    return o;
}
static std::string neo_lower(const std::string& s) {
    std::string o = s;
    for (size_t i = 0; i < o.size(); i++) {
        unsigned char c = (unsigned char)o[i];
        if (c >= 'A' && c <= 'Z') o[i] = (char)(c + 32);
        else if (c == 0xC3 && i + 1 < o.size()) {
            unsigned char d = (unsigned char)o[i + 1];
            if (d >= 0x80 && d <= 0x9E && d != 0x97) o[i + 1] = (char)(d + 0x20);
        }
    }
    return o;
}
// .stab : onglet résumé — icône ROM (repli picto) + label, actif = liseré
static void neo_stab(ImDrawList* dl, ImVec2 p0, ImVec2 p1, int ic,
                     const char* lb, bool on, float u, GLuint tex = 0) {
    ImU32 tc = on ? IM_COL32(44, 54, 76, 255)
                  : IM_COL32(110, 125, 150, 255);
    if (on) {
        neo_gfill(dl, p0, p1, 7.f * u,
            IM_COL32(232, 69, 90, 33), IM_COL32(232, 69, 90, 0));
        dl->PushClipRect({p0.x, p1.y - 2.f * u}, p1, true);
        dl->AddRect(p0, {p1.x, p1.y + 9.f * u}, IM_COL32(232, 69, 90, 255),
            9.f * u, 0, 2.f * u);
        dl->PopClipRect();
    }
    float cx = (p0.x + p1.x) * 0.5f,
          cy = p0.y + 11.f * u, r = 6.5f * u;
    if (tex) {                          // icône ROM authentique
        dl->AddImage((ImTextureID)(intptr_t)tex,
            {cx - 10.5f * u, cy - 10.5f * u},
            {cx + 10.5f * u, cy + 10.5f * u},
            {0, 0}, {1, 1},
            on ? IM_COL32(255, 255, 255, 255)
               : IM_COL32(205, 214, 230, 215));
    } else
    switch (ic) {                       // pictos dessinés (fonte limitée)
    case 0:                             // INFOS : i cerclé
        dl->AddCircle({cx, cy}, r, tc, 0, 1.4f * u);
        dl->AddCircleFilled({cx, cy - r * 0.45f}, 0.9f * u, tc);
        dl->AddLine({cx, cy - r * 0.1f}, {cx, cy + r * 0.55f}, tc,
            1.4f * u);
        break;
    case 1:                             // MÉMO : document
        dl->AddRect({cx - r * 0.75f, cy - r}, {cx + r * 0.75f, cy + r},
            tc, 1.5f * u, 0, 1.4f * u);
        for (int k = 0; k < 3; k++)
            dl->AddLine({cx - r * 0.45f, cy - r * 0.5f + k * r * 0.42f},
                {cx + r * 0.45f, cy - r * 0.5f + k * r * 0.42f}, tc,
                1.1f * u);
        break;
    case 2:                             // STATS : 3 barres
        for (int k = 0; k < 3; k++)
            dl->AddRectFilled(
                {cx - r + k * r * 0.75f, cy + r - (k + 1) * r * 0.6f},
                {cx - r + k * r * 0.75f + r * 0.45f, cy + r}, tc);
        break;
    case 3: {                           // IV/EV : losange
        ImVec2 v[4] = {{cx, cy - r}, {cx + r * 0.75f, cy},
                       {cx, cy + r}, {cx - r * 0.75f, cy}};
        dl->AddPolyline(v, 4, tc, ImDrawFlags_Closed, 1.4f * u);
        dl->AddCircleFilled({cx, cy}, 1.4f * u, tc);
        break; }
    case 4:                             // CAPACITÉS : épées croisées
        dl->AddLine({cx - r, cy - r}, {cx + r, cy + r}, tc, 1.6f * u);
        dl->AddLine({cx + r, cy - r}, {cx - r, cy + r}, tc, 1.6f * u);
        dl->AddLine({cx - r * 0.4f, cy - r}, {cx - r, cy - r * 0.4f}, tc,
            1.1f * u);
        dl->AddLine({cx + r * 0.4f, cy - r}, {cx + r, cy - r * 0.4f}, tc,
            1.1f * u);
        break;
    default:                            // RUBANS : rosette
        dl->AddCircle({cx, cy - r * 0.3f}, r * 0.6f, tc, 0, 1.4f * u);
        dl->AddLine({cx - r * 0.3f, cy + r * 0.2f},
                    {cx - r * 0.55f, cy + r}, tc, 1.4f * u);
        dl->AddLine({cx + r * 0.3f, cy + r * 0.2f},
                    {cx + r * 0.55f, cy + r}, tc, 1.4f * u);
        break;
    }
    float lw = neo_tw(lb, 9.f * u);
    neo_txt(dl, lb, cx - lw * 0.5f, p1.y - 14.f * u, tc, 9.f * u);
}
// .pock : poche du sac — icône + nom + compteur, actif = liseré + voile
static void neo_pock(ImDrawList* dl, ImVec2 p0, ImVec2 p1, const char* n,
                     int cnt, bool on, float u, GLuint icon) {
    if (on) {
        dl->AddRectFilled(p0, p1, IM_COL32(232, 69, 90, 31), 10.f * u);
        dl->AddRect(p0, p1, IM_COL32(232, 69, 90, 153), 10.f * u, 0, 1.5f);
    }
    float cx = (p0.x + p1.x) * 0.5f;
    if (icon)
        dl->AddImage((ImTextureID)(intptr_t)icon,
            {cx - 15.f * u, p0.y + 8.f * u},
            {cx + 15.f * u, p0.y + 38.f * u}, {0, 0}, {1, 1},
            on ? IM_COL32(255, 255, 255, 255)
               : IM_COL32(200, 200, 210, 150));
    float nw = neo_tw(n, 8.5f * u);
    neo_txt(dl, n, cx - nw * 0.5f, p1.y - 24.f * u,
        on ? IM_COL32(240, 184, 192, 255) : IM_COL32(142, 161, 194, 255),
        8.5f * u);
    if (cnt >= 0) {
        char cb[8]; snprintf(cb, sizeof cb, "%d", cnt);
        float cw = neo_tw(cb, 8.f * u);
        neo_txt(dl, cb, cx - cw * 0.5f, p1.y - 13.f * u,
            IM_COL32(67, 82, 122, 255), 8.f * u);
    }
}
// .stbar : piste stat + fill bleu dégradé
static void neo_stbar(ImDrawList* dl, ImVec2 p0, float w, float frac,
                      float h, ImU32 c0, ImU32 c1) {
    frac = frac < 0 ? 0 : frac > 1 ? 1 : frac;
    dl->AddRectFilled(p0, {p0.x + w, p0.y + h}, IM_COL32(26, 36, 56, 255),
        3.f);
    if (frac > 0.f)
        dl->AddRectFilledMultiColor(p0, {p0.x + w * frac, p0.y + h},
            c0, c1, c1, c0);
}
// couleur qualité IV : 31 or / ≥26 vert / ≥16 acier / sinon orange
static ImU32 neo_ivq(int v) {
    return v == 31 ? IM_COL32(232, 176, 69, 255)
        : v >= 26 ? IM_COL32(74, 200, 138, 255)
        : v >= 16 ? IM_COL32(142, 161, 194, 255)
                  : IM_COL32(232, 115, 74, 255);
}
// couleur de type DS (0..17) — même table que la maquette
static ImU32 neo_type(int t) {
    static const ImU32 TC[18] = {
        IM_COL32(168, 168, 120, 255),  // 0 Normal
        IM_COL32(192, 48, 40, 255),    // 1 Combat
        IM_COL32(168, 144, 240, 255),  // 2 Vol
        IM_COL32(160, 64, 160, 255),   // 3 Poison
        IM_COL32(224, 192, 104, 255),  // 4 Sol
        IM_COL32(184, 160, 56, 255),   // 5 Roche
        IM_COL32(168, 184, 32, 255),   // 6 Insecte
        IM_COL32(112, 88, 152, 255),   // 7 Spectre
        IM_COL32(184, 184, 208, 255),  // 8 Acier
        IM_COL32(120, 120, 130, 255),  // 9 ???
        IM_COL32(240, 128, 48, 255),   // 10 Feu
        IM_COL32(104, 144, 240, 255),  // 11 Eau
        IM_COL32(120, 200, 80, 255),   // 12 Plante
        IM_COL32(248, 208, 48, 255),   // 13 Électrik
        IM_COL32(248, 88, 136, 255),   // 14 Psy
        IM_COL32(152, 216, 216, 255),  // 15 Glace
        IM_COL32(112, 56, 248, 255),   // 16 Dragon
        IM_COL32(112, 88, 72, 255)};   // 17 Ténèbres
    return (t >= 0 && t < 18) ? TC[t] : TC[9];
}
// .cur : petit curseur triangulaire rouge (bob)
[[maybe_unused]] static void neo_cur(ImDrawList* dl, float x, float y,
                                     float u, float t) {
    float dy = sinf(t * 6.2831853f) * 3.f * u;
    dl->AddTriangleFilled({x, y + dy}, {x + 10.f * u, y + dy},
        {x + 5.f * u, y + 7.f * u + dy}, IM_COL32(232, 69, 90, 255));
}
// ── briques UI DS réelles : police NFGR (pl_font) + cadre pl_winframe ────────
static GLuint ui_upload(const Image& im, bool linear = false) {
    GLuint t = 0;
    glGenTextures(1, &t);
    glBindTexture(GL_TEXTURE_2D, t);
    glPixelStorei(GL_UNPACK_ALIGNMENT, 1);
    glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, im.w, im.h, 0, GL_RGBA,
        GL_UNSIGNED_BYTE, im.px.data());
    GLint f = linear ? GL_LINEAR : GL_NEAREST;
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, f);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, f);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
    return t;
}
// logo OpenPlatinum « Horizon » : masque radial -> le carré bleu nuit
// de l'image se fond dans le décor (aucun bord visible)
static GLuint title_logo_tex(int* w, int* h) {
    static GLuint t = 0; static int tw = 0, th = 0, tried = 0;
    if (!tried) {
        tried = 1;
        int ww, hh;
        if (unsigned char* d = stbi_load(up_path("logo_op.png").c_str(),
                &ww, &hh, nullptr, 4)) {
            // fondu elliptique très doux : opaque jusqu'à r=0.40, smoothstep
            // jusqu'à 0.86 — le bord s'évanouit dans le halo, aucune ligne
            float cx = ww * 0.5f, cy = hh * 0.46f;
            for (int y = 0; y < hh; y++)
                for (int x = 0; x < ww; x++) {
                    float dx = (x - cx) / (ww * 0.52f),
                          dy = (y - cy) / (hh * 0.50f);
                    float r = sqrtf(dx * dx + dy * dy);
                    float t = (r - 0.40f) / 0.46f;
                    t = fminf(1.f, fmaxf(0.f, t));
                    float a = 1.f - t * t * (3.f - 2.f * t);   // smoothstep
                    int i = (y * ww + x) * 4;
                    d[i + 3] = (unsigned char)(d[i + 3] * a);
                }
            Image im; im.create(ww, hh);
            memcpy(im.px.data(), d, (size_t)ww * hh * 4);
            stbi_image_free(d);
            t = ui_upload(im, true);
            tw = ww; th = hh;
        }
    }
    if (w) *w = tw; if (h) *h = th;
    return t;
}
// texture UI pixel-art (kit PixelLab : ui/*.png) — chargée une fois
static GLuint ui_png_tex(const char* name) {
    static std::map<std::string, GLuint> cache;
    auto it = cache.find(name);
    if (it != cache.end()) return it->second;
    GLuint t = 0;
    int ww, hh;
    if (unsigned char* d = stbi_load(up_path((std::string("ui/") + name).c_str()).c_str(),
            &ww, &hh, nullptr, 4)) {
        Image im; im.create(ww, hh);
        memcpy(im.px.data(), d, (size_t)ww * hh * 4);
        stbi_image_free(d);
        t = ui_upload(im, true);
    }
    cache[name] = t;
    return t;
}
// icônes animées PixelLab : « base_0.png .. base_N.png » dans ui/
static GLuint ui_anim_tex(const char* base) {
    struct Anim { std::vector<GLuint> fr; };
    static std::map<std::string, Anim> cache;
    auto it = cache.find(base);
    if (it == cache.end()) {
        Anim a;
        for (int i = 0; i < 32; i++) {
            char nm[80]; snprintf(nm, sizeof nm, "%s_%d.png", base, i);
            int ww, hh;
            unsigned char* d = stbi_load(up_path((std::string("ui/") + nm).c_str()).c_str(),
                &ww, &hh, nullptr, 4);
            if (!d) break;
            Image im; im.create(ww, hh);
            memcpy(im.px.data(), d, (size_t)ww * hh * 4);
            stbi_image_free(d);
            a.fr.push_back(ui_upload(im, true));
        }
        it = cache.emplace(base, std::move(a)).first;
    }
    if (it->second.fr.empty()) return 0;
    int fr = (int)(ImGui::GetTime() * 9.0) % (int)it->second.fr.size();
    return it->second.fr[fr];
}
// icône de menu : animée si les frames existent, sinon « base.png »
static GLuint ui_icon(const char* base) {
    if (GLuint t = ui_anim_tex(base)) return t;
    char nm[80]; snprintf(nm, sizeof nm, "%s.png", base);
    return ui_png_tex(nm);
}
// ── fond animé du titre : 14 frames pixel-art « lac aube » (PixelLab)
static GLuint lake_frame_tex(int i) {
    static GLuint t[14] = {};
    static bool tried[14] = {};
    if (!tried[i]) {
        tried[i] = true;
        int ww, hh;
        char nm[48]; snprintf(nm, sizeof nm, "title/f%d.png", i + 1);
        if (unsigned char* d = stbi_load(up_path((std::string("ui/") + nm).c_str()).c_str(),
                &ww, &hh, nullptr, 4)) {
            Image im; im.create(ww, hh);
            memcpy(im.px.data(), d, (size_t)ww * hh * 4);
            stbi_image_free(d);
            t[i] = ui_upload(im, true);
        }
    }
    return t[i];
}
// dessine le lac animé plein écran + voiles de lisibilité (bas + gauche)
static void lake_bg(ImDrawList* dl, ImVec2 io, double t) {
    int fr = (int)(t * 8.5) % 14;
    if (GLuint tx = lake_frame_tex(fr))
        dl->AddImage((ImTextureID)(intptr_t)tx, {0, 0}, {io.x, io.y});
    int y0 = (int)(io.y * 0.55f);
    for (int y = y0; y < (int)io.y; y += 4) {
        float a = 120.f * (y - y0) / (float)(io.y - y0);
        dl->AddRectFilled({0, (float)y}, {io.x, (float)y + 4.f},
            IM_COL32(8, 12, 26, (int)a));
    }
    int x1 = (int)(io.x * 0.46f);
    for (int x = 0; x < x1; x += 4) {
        float a = 85.f * (1.f - (float)x / x1);
        dl->AddRectFilled({(float)x, 0}, {(float)x + 4.f, io.y},
            IM_COL32(8, 12, 26, (int)a));
    }
}
// wordmark « OpenPlatinum » (Open léger + Platinum plein) + filet corail
static void lake_wordmark(ImDrawList* dl, float u, float tx, float ty, float px) {
    float w1 = neo_txt(dl, "Open", tx, ty, IM_COL32(215, 222, 240, 255), px);
    float w2 = neo_tw("Platinum", px);
    neo_txt(dl, "Platinum", tx + w1 + 5.f * u, ty,
            IM_COL32(248, 250, 255, 255), px);
    dl->AddRectFilled({tx + 3.f * u, ty + px * 1.22f},
        {tx + w1 + 5.f * u + w2 - 3.f * u, ty + px * 1.22f + 2.5f * u},
        IM_COL32(238, 72, 80, 255));
    neo_txt(dl, u > 1.f ? "POKÉMON PLATINE — REMAKE NATIF PC"
                        : "POKEMON PLATINE - REMAKE NATIF PC",
        tx + 4.f * u, ty + px * 1.48f, IM_COL32(215, 224, 242, 255),
        px * 0.22f);
}
// logo d'écran : icône PixelLab dans un chip blanc bord gris
static void ui_logo(ImDrawList* dl, const char* png, ImVec2 c, float r) {
    dl->AddRectFilled({c.x - r, c.y - r + 2.5f},
        {c.x + r, c.y + r + 2.5f}, IM_COL32(0, 0, 0, 40), r * 0.55f);
    dl->AddRectFilled({c.x - r, c.y - r}, {c.x + r, c.y + r},
        IM_COL32(252, 253, 255, 245), r * 0.55f);
    dl->AddRect({c.x - r, c.y - r}, {c.x + r, c.y + r},
        IM_COL32(168, 182, 202, 255), r * 0.55f, 0, 1.2f);
    if (GLuint t = ui_png_tex(png))
        dl->AddImage((ImTextureID)(intptr_t)t,
            {c.x - r * 0.68f, c.y - r * 0.68f},
            {c.x + r * 0.68f, c.y + r * 0.68f});
}
// petite pokéball procédurale (ornement capsule)
static void ui_poke(ImDrawList* dl, ImVec2 c, float r) {
    dl->AddCircleFilled(c, r, IM_COL32(40, 50, 70, 255), 20);
    dl->PathArcTo(c, r - 1.f, 3.14159265f, 6.2831853f);
    dl->PathFillConvex(IM_COL32(232, 70, 84, 255));
    dl->PathArcTo(c, r - 1.f, 0.f, 3.14159265f);
    dl->PathFillConvex(IM_COL32(248, 250, 253, 255));
    dl->AddRectFilled({c.x - r + 0.5f, c.y - r * 0.13f},
        {c.x + r - 0.5f, c.y + r * 0.13f}, IM_COL32(40, 50, 70, 255));
    dl->AddCircleFilled(c, r * 0.32f, IM_COL32(40, 50, 70, 255), 12);
    dl->AddCircleFilled(c, r * 0.2f, IM_COL32(248, 250, 253, 255), 12);
}
// fond « Horizon » : ciel navy + halo radial haut + ligne d'horizon
// lumineuse (clin d'oeil au Monde Distorsion) — partagé titre/menu
static void horizon_bg(ImDrawList* dl, ImVec2 io, float hy) {
    // ciel navy : un peu plus clair vers le haut, sombre sous l'horizon
    dl->AddRectFilledMultiColor({0, 0}, {io.x, hy},
        IM_COL32(14, 20, 40, 255), IM_COL32(14, 20, 40, 255),
        IM_COL32(9, 12, 24, 255), IM_COL32(9, 12, 24, 255));
    dl->AddRectFilledMultiColor({0, hy}, io,
        IM_COL32(9, 12, 24, 255), IM_COL32(9, 12, 24, 255),
        IM_COL32(6, 8, 17, 255), IM_COL32(6, 8, 17, 255));
    // poussière d'étoiles au-dessus de l'horizon (hash déterministe)
    for (int i = 0; i < 110; i++) {
        uint32_t h = (uint32_t)(i + 1) * 2654435761u;
        float sx = (h & 0xffff) / 65535.f * io.x;
        float sy = ((h >> 16) & 0xffff) / 65535.f * (hy - 24.f);
        int a = 10 + ((h >> 8) & 38);
        float r = (h & 7) ? 1.f : 1.7f;
        dl->AddCircleFilled({sx, sy}, r, IM_COL32(196, 214, 255, a), 6);
    }
    // halo doux derrière le logo : ellipses concentriques à alpha
    // croissant = dégradé radial (pas de blob opaque)
    ImVec2 cc{io.x * 0.5f, hy * 0.52f};
    for (int k = 26; k >= 1; k--) {
        float rf = k / 26.f;
        dl->AddEllipseFilled(cc, {io.x * 0.33f * rf + 1.f,
            hy * 0.88f * rf + 1.f},
            IM_COL32(32, 52, 104, 3 + (int)((1.f - rf) * 7.f)), 0.f, 64);
    }
    // horizon lumineux : filet central + dégradés latéraux
    float mx = io.x * 0.5f;
    dl->AddRectFilledMultiColor({0, hy - 1.f}, {mx, hy + 1.f},
        IM_COL32(90, 138, 240, 0), IM_COL32(168, 192, 255, 255),
        IM_COL32(168, 192, 255, 255), IM_COL32(90, 138, 240, 0));
    dl->AddRectFilledMultiColor({mx, hy - 1.f}, {io.x, hy + 1.f},
        IM_COL32(168, 192, 255, 255), IM_COL32(90, 138, 240, 0),
        IM_COL32(90, 138, 240, 0), IM_COL32(168, 192, 255, 255));
    // reflet dégradé sous la ligne
    for (int k = 0; k < 9; k++)
        dl->AddRectFilledMultiColor(
            {0, hy + 2.f + k * 10.f}, {io.x, hy + 12.f + k * 10.f},
            IM_COL32(90, 138, 240, 24 - k * 2), IM_COL32(90, 138, 240, 24 - k * 2),
            IM_COL32(0, 0, 0, 0), IM_COL32(0, 0, 0, 0));
    dl->AddEllipseFilled({io.x * 0.5f, hy}, {io.x * 0.30f, io.y * 0.11f},
        IM_COL32(90, 138, 240, 15), 0.f, 48);
    // liseré rouge chaud tout en bas (accent du logo)
    dl->AddRectFilledMultiColor({0, io.y - 34.f}, io,
        IM_COL32(0, 0, 0, 0), IM_COL32(0, 0, 0, 0),
        IM_COL32(232, 69, 90, 26), IM_COL32(232, 69, 90, 26));
}
// décors de combat HD peints (battlebg/*.png) + surcouches ciel/ombre
static GLuint battleback_tex(const char* name) {
    static std::map<std::string, GLuint> c;
    auto it = c.find(name);
    if (it != c.end()) return it->second;
    GLuint t = 0;
    int w = 0, h = 0;
    std::string p = up_path("battlebg/") + name + ".png";
    if (unsigned char* d = stbi_load(p.c_str(), &w, &h, nullptr, 4)) {
        Image im; im.create(w, h);
        memcpy(im.px.data(), d, (size_t)w * h * 4);
        stbi_image_free(d);
        t = ui_upload(im, true);
    }
    c[name] = t;
    return t;
}
// encres police DS (pl_font m7) : [fg][ombre] par code couleur du jeu
static const ImU32 DS_FG[8]  = {IM_COL32(80,80,88,255), IM_COL32(232,32,16,255),
    IM_COL32(0,112,248,255), IM_COL32(0,0,0,255), IM_COL32(40,168,32,255),
    IM_COL32(248,248,248,255), IM_COL32(216,216,216,255), IM_COL32(248,248,248,255)};
static const ImU32 DS_SH[8]  = {IM_COL32(160,160,168,255), IM_COL32(248,168,184,255),
    IM_COL32(120,184,232,255), IM_COL32(120,120,120,255), IM_COL32(160,230,160,255),
    IM_COL32(88,88,96,255), IM_COL32(144,208,248,255), IM_COL32(0,0,0,255)};
static spr::Nfgr g_dfont;
static GLuint g_fatlas[8 * 5] = {};             // [theme*8 + ci]
static const int g_fss = 4;                     // atlas suréchantillonné
static bool g_font_try = false;
static bool ds_font_ready(Nds& db) {
    if (!g_font_try) {
        g_font_try = true;
        auto fn = db.narc("/graphic/pl_font.narc");
        if (fn && fn->count() > 1)
            g_dfont = spr::parse_nfgr(fn->member(1));    // FONT_MESSAGE
    }
    return g_dfont.nglyphs > 0;
}
static GLuint ds_font_tex(int ci) {
    if (ci < 0 || ci > 7) ci = 0;
    int th = g_theme_eff; if (th < 0 || th > 4) th = 0;
    if (th == 4) th = 3;              // repli : palette NÉO pour les écrans non portés
    int slot = th * 8 + ci;
    if (!g_fatlas[slot]) {
        // atlas ×g_fss : échantillonné LINEAR = lissé net (pas flou)
        ImU32 fg = ui_theme()->fg[ci], sh = ui_theme()->sh[ci];
        auto im = spr::font_atlas(g_dfont,
            RGBAf{(float)(fg & 255), (float)((fg >> 8) & 255),
                  (float)((fg >> 16) & 255), 255},
            RGBAf{(float)(sh & 255), (float)((sh >> 8) & 255),
                  (float)((sh >> 16) & 255), 255}, g_fss);
        if (im) g_fatlas[slot] = ui_upload(*im, true);
    }
    return g_fatlas[slot];
}
// dessine une chaîne glyphe par glyphe (avances natives du NFGR)
static float ds_text(ImDrawList* dl, const std::string& s, float x, float y,
                     int ci, float scale) {
    if (g_theme_eff) {
        // thème : police système lisse — grande instance si dispo (Fonts[1] 64px)
        auto& fl = *ImGui::GetIO().Fonts;
        ImFont* f = fl.Fonts.Size > 1 ? fl.Fonts[1] : fl.Fonts[0];
        float ch = g_dfont.cellH > 0 ? (float)g_dfont.cellH : 16.f;
        float px = std::max(8.f, ch * scale * 0.82f);
        ImU32 sh = ui_theme()->sh[ci & 7];
        // ombre douce : halo léger autour + décalage bas-droite
        ImU32 halo = (sh & 0x00FFFFFFu) | (((sh >> 24) / 3) << 24);
        for (auto o : {ImVec2(1, 0), ImVec2(-1, 0), ImVec2(0, 1), ImVec2(0, -1)})
            dl->AddText(f, px, {x + o.x, y + o.y}, halo, s.c_str());
        dl->AddText(f, px, {x + px * 0.045f, y + px * 0.05f}, sh, s.c_str());
        dl->AddText(f, px, {x, y}, ui_theme()->fg[ci & 7], s.c_str());
        return f->CalcTextSizeA(px, 1e30f, 0, s.c_str()).x;
    }
    if (!g_dfont.nglyphs) { dl->AddText({x, y}, ui_theme()->fg[ci & 7], s.c_str()); return 0; }
    GLuint at = ds_font_tex(ci);
    float x0 = x;
    int awt = 16 * g_dfont.cellW * g_fss,
        aht = ((g_dfont.nglyphs + 15) / 16) * g_dfont.cellH * g_fss;
    for (size_t k = 0; k < s.size(); ) {
        int cp = msg_next_utf8(s, k);
        if (cp < 0) break;
        int gc = msg_char_code_of((char32_t)cp);
        int g = gc > 0 ? gc - 1 : -1;
        int w = g >= 0 ? g_dfont.glyph_w(g) : g_dfont.cellW;
        if (!w) w = g_dfont.cellW;
        if (g >= 0 && cp != ' ') {
            float pi = 0.4f * g_fss;   // retrait UV : évite le saignement
            float u0 = ((g % 16) * g_dfont.cellW * g_fss + pi) / awt,
                  v0 = ((g / 16) * g_dfont.cellH * g_fss + pi) / aht,
                  u1 = ((g % 16 + 1) * g_dfont.cellW * g_fss - pi) / awt,
                  v1 = ((g / 16 + 1) * g_dfont.cellH * g_fss - pi) / aht;
            // calage pixel : quad aligné sur des coordonnées entières pour
            // éviter le flou « haché » du LINEAR à offset fractionnaire
            float gx = roundf(x), gy = roundf(y),
                  gw2 = roundf(g_dfont.cellW * scale),
                  gh2 = roundf(g_dfont.cellH * scale);
            dl->AddImage((ImTextureID)(intptr_t)at, ImVec2(gx, gy),
                ImVec2(gx + gw2, gy + gh2),
                ImVec2(u0, v0), ImVec2(u1, v1));
        }
        x += w * scale;
    }
    return x - x0;
}
// mesure d'une chaîne en pixels DS (échelle 1 = cellules natives)
static float ds_text_w(const std::string& s, float scale) {
    if (g_theme_eff) {
        auto& fl = *ImGui::GetIO().Fonts;
        ImFont* f = fl.Fonts.Size > 1 ? fl.Fonts[1] : fl.Fonts[0];
        float ch = g_dfont.cellH > 0 ? (float)g_dfont.cellH : 16.f;
        float px = std::max(8.f, ch * scale * 0.82f);
        return f->CalcTextSizeA(px, 1e30f, 0, s.c_str()).x;
    }
    float w = 0;
    for (size_t k = 0; k < s.size(); ) {
        int cp = msg_next_utf8(s, k);
        if (cp < 0) break;
        int gc = msg_char_code_of((char32_t)cp);
        int g = gc > 0 ? gc - 1 : -1;
        int gw = g >= 0 ? g_dfont.glyph_w(g) : g_dfont.cellW;
        w += (gw ? gw : g_dfont.cellW) * scale;
    }
    return w;
}
// ── couche UI en pixels DS (256x192), upscalée à la fenêtre ─────────────────
// toutes les positions ci-dessous sont en coordonnées DS natives (tuiles 8px)
static float g_uds = 1.f, g_udx = 0.f, g_udy = 0.f;
static inline ImVec2 dp(float x, float y) {
    return ImVec2(g_udx + x * g_uds, g_udy + y * g_uds);
}
// plateau DS 256x192 : unité = hauteur pleine × ÉCHELLE UI (option),
// centrée horizontalement ; bottom = collée en bas (boîtes de dialogue
// posées sur le monde), sinon centrée verticalement comme OpenSinnoh.
static inline void ds_board(float sw, float sh, bool bottom = false) {
    int s = g_opts.ui_scale;
    if (s < 50) s = 50; if (s > 100) s = 100;
    g_uds = sh / 192.f * (s / 100.f);
    g_udx = (sw - 256.f * g_uds) * 0.5f;
    g_udy = bottom ? sh - 192.f * g_uds : (sh - 192.f * g_uds) * 0.5f;
}
// texte NFGR en coordonnées DS (taille native, espacement lettre 0)
static float dt_text(ImDrawList* dl, const std::string& s, float x, float y,
                     int ci) {
    ds_text(dl, s, g_udx + x * g_uds, g_udy + y * g_uds, ci, g_uds);
    return 0;
}
// largeur en pixels DS (échelle native)
static float dt_text_w(const std::string& s) { return ds_text_w(s, 1.f); }
// texte de dialogue agrandi : la police message ne remplit qu'à moitié sa
// cellule 16px — un quad légèrement agrandi recentré dans la ligne rend le
// texte plus lisible sans casser la boîte (pitch 16px conservé)
static const float DLG_TS = 1.3f;
// option TAILLE TEXTE : petit = DS natif, normal/grand = agrandi
static inline float dlg_ts_px() {         // échelle de la police pixel DS
    int s = g_opts.text_size;
    if (s < 0 || s > 2) s = 1;
    static const float TS[] = {1.f, 1.3f, 1.5f};
    return TS[s];
}
static inline float dlg_ts() {            // échelle du contexte courant
    int s = g_opts.text_size;
    if (s < 0 || s > 2) s = 1;
    static const float TT[] = {1.f, 1.1f, 1.25f};      // police lisse thème
    return g_theme_eff ? TT[s] : dlg_ts_px();
}
static float dt_text_big(ImDrawList* dl, const std::string& s, float x,
                        float y, int ci) {
    // recentrage vertical seulement pour la police pixel (la police lisse
    // du thème part déjà du haut de la cellule)
    float ts = dlg_ts();
    float off = g_theme_eff ? 0.f
                           : g_dfont.cellH * g_uds * (ts - 1.f) * 0.5f;
    ds_text(dl, s, g_udx + x * g_uds, g_udy + y * g_uds - off, ci, g_uds * ts);
    return 0;
}
static float dt_text_big_w(const std::string& s) {
    return ds_text_w(s, dlg_ts());
}
// mesure d'une plage s[b..e) — identique au linew du wrap de la boîte
// message (espaces via le glyphe 0, glyphes inconnus = 8 px)
static float dlg_linew(const std::string& s, size_t b, size_t e) {
    // métrique identique au rendu de la boîte monde (glyphes DS, avance
    // glyph_w/cellW) — sinon la page paginée peut déborder en thème
    float w = 0;
    for (size_t k = b; k < e; ) {
        int cp = msg_next_utf8(s, k);
        if (cp < 0) break;
        int g = cp == ' ' ? 0 : msg_char_code_of((char32_t)cp) - 1;
        if (!g_dfont.nglyphs || g < 0) { w += 8.f; continue; }
        int gw = g_dfont.glyph_w(g);
        w += gw ? gw : g_dfont.cellW;
    }
    return w * dlg_ts_px();     // rendu agrandi -> pagination identique
}
// pages du clavier de nommage POP (maquette .s04) : lignes de 10 touches
