    auto u8enc = [](int cp, char* u8) -> int {
        if (cp < 0x80) { u8[0] = (char)cp; return 1; }
        if (cp < 0x800) {
            u8[0] = (char)(0xC0 | (cp >> 6));
            u8[1] = (char)(0x80 | (cp & 63));
            return 2;
        }
        u8[0] = (char)(0xE0 | (cp >> 12));
        u8[1] = (char)(0x80 | ((cp >> 6) & 63));
        u8[2] = (char)(0x80 | (cp & 63));
        return 3;
    };
    std::function<int()> nm_nlen;
