                             igender = atoi(argv[i + 1]);
                     iskin_build();
                     iset_txt(tr("Choisis ton apparence.","Choose your look."));
                     break;
            case 11: ist = I_SKIN; iskin_build(); iskin_edit = 1;
                     iset_txt(tr("Choisis ton apparence.","Choose your look."));
                     break;
            case 12: case 13: ist = I_SKIN; iskin_build();
                     for (int i = 1; i + 1 < argc; i++)
                         if (!strcmp(argv[i], "--gender"))
                             igender = atoi(argv[i + 1]);
