    double tv_zap = -9.0;                           // instant du dernier zapping
    double tv_off_t = -1.0;                         // extinction CRT en cours
    bool tv_had_feed = false;                       // la scène a diffusé du texte
    long tv_quiz_skip = -1;                         // tour du quiz révélé (E)
    int menu_msel = 0;
