    auto xmenu_opts = [&world]() {           // options visibles (ordre DS)
        std::vector<int> v;
        if (world.dex_obtained()) v.push_back(0);
        if (world.enc_raw()) v.push_back(7);           // ZONE : rencontres du lieu
        if (world.has_starter()) v.push_back(1);
        v.insert(v.end(), {2, 3, 4, 5, 6});  // Sac, nom, Sauver, Options, Quitter
        return v;
    };
    auto ui_enter = [&](int opt) -> int {
        switch (opt) {
            case 0: dex_sel = 0; dex_scroll = 0; return UI_DEX;
            case 1: return UI_PARTY;
            case 2: bag_pocket = 0; menu_sel = 0; return UI_BAG;
            case 3: return UI_CARD;
            case 4: save_st = 0; menu_sel = 0; return UI_SAVE;
            case 5: menu_sel = 0; opt_zone = 1; opt_cat = 0; return UI_OPTIONS;
            case 6: return UI_NONE;          // Quitter
            case 7: enc_tab = 0; enc_scr = 0; return UI_ENC;
        }
        return UI_NONE;
    };
    auto repel_apply = [&]() {              // utilise un Repousse du sac
        int rid = 0;
        if (world.bag().count(world.repel_last()) &&
            world.bag().at(world.repel_last()) > 0)
            rid = world.repel_last();
        else
            for (int id : {77, 76, 79})       // Max > Super > Repousse
                if (world.bag().count(id) && world.bag().at(id) > 0) {
                    rid = id; break; }
        if (rid && world.item_field_use(rid) == 4) {
            world.vm().bag_add(rid, -1);
            repel_dlg = 2; repel_t = 1.4f;
        } else repel_dlg = 0;
    };
