                ScriptVM::PartyMon pm; pm.species = sp; pm.level = lv;
                auto bm0 = battle_make(&db, sp, lv);
                pm.ivs = bm0.ivs; pm.pid = bm0.pid; pm.exp = bm0.exp;
                pm.hp = bm0.maxhp;
                pm.nmoves = bm0.nmoves;
                for (int k = 0; k < pm.nmoves; k++) {
                    pm.moves[k] = bm0.moves[k]; pm.pp[k] = bm0.pp[k]; }
                world.pcbox()[sl] = pm;
