                    bg->AddText(f, epx, {tx, ey}, tc, lb);
                    if (sel) {
                        // losange rouge à gauche de l'entrée active
                        float dy2 = ey + epx * 0.55f,
                              dx2 = tx - 26.f * g_uds;
                        float dr = 5.f * g_uds;
                        bg->AddQuadFilled({dx2, dy2 - dr},
                            {dx2 + dr, dy2}, {dx2, dy2 + dr},
                            {dx2 - dr, dy2}, IM_COL32(232, 69, 90, 255));
                        // filet lumineux sous l'entrée
                        float uy2 = ey + 26.f * g_uds;
                        bg->AddRectFilledMultiColor(
                            {ex, uy2}, {ex + cw * 0.5f, uy2 + 2.f * g_uds},
                            IM_COL32(232, 69, 90, 0), IM_COL32(232, 69, 90, 220),
                            IM_COL32(232, 69, 90, 220), IM_COL32(232, 69, 90, 0));
                        bg->AddRectFilledMultiColor(
                            {ex + cw * 0.5f, uy2}, {ex + cw, uy2 + 2.f * g_uds},
                            IM_COL32(232, 69, 90, 220), IM_COL32(232, 69, 90, 0),
                            IM_COL32(232, 69, 90, 0), IM_COL32(232, 69, 90, 220));
                    }
                    if (sb && *sb) {
                        float sx = ex + (cw - sw_[i]) * 0.5f;
                        bg->AddText(f, spx, {sx, ey + 34.f * g_uds},
                            IM_COL32(67, 82, 122, 255), sb);
                    }
                    imenu_rc.push_back({{p0.x, p0.y, p1.x, p1.y}, i});
                    ex += cw + gap;
